69	    /// Checks if a member expression's base object may be mutated.
70	    ///
71	    /// This is used to prevent incorrect transformations like:
72	    /// `x.y || (x = {}, x.y = 3)` → `x.y ||= (x = {}, 3)`
73	    ///
74	    /// The `||=` operator evaluates `x.y` (capturing `x`) before the RHS reassigns `x`,
75	    /// which would change the semantics.
76	    pub fn member_object_may_be_mutated(
77	        assignment_target: &AssignmentTarget<'a>,
78	        ctx: &TraverseCtx<'a>,
79	    ) -> bool {
80	        let object = match assignment_target {
81	            AssignmentTarget::ComputedMemberExpression(member_expr) => &member_expr.object,
82	            AssignmentTarget::PrivateFieldExpression(member_expr) => &member_expr.object,
83	            AssignmentTarget::StaticMemberExpression(member_expr) => &member_expr.object,
84	            _ => return false,
85	        };
86	
87	        Self::is_expression_that_reference_may_change(object, ctx)
88	    }
89	
90	    /// Checks if an expression's reference may change due to mutation.
91	    ///
92	    /// Returns `true` if the expression references a symbol that may be mutated,
93	    /// or if the expression is not a simple identifier/this reference.
94	    pub fn is_expression_that_reference_may_change(
95	        expr: &Expression<'a>,
96	        ctx: &TraverseCtx<'a>,
97	    ) -> bool {
98	        match expr {
99	            Expression::Identifier(id) => {
100	                if let Some(symbol_id) = ctx.scoping().get_reference(id.reference_id()).symbol_id()
101	                {
102	                    Self::is_symbol_mutated(symbol_id, ctx)
103	                } else {
104	                    true
105	                }
106	            }
107	            Expression::ThisExpression(_) => false,
108	            _ => true,
109	        }
110	    }
