112	    /// Check if a symbol is mutated, using the O(1) cached `write_references_count`
113	    /// from `SymbolValue` when available, falling back to the O(num_refs) scan in
114	    /// `Scoping::symbol_is_mutated` for symbols without cached values.
115	    ///
116	    /// Only variable declarators have cached values (populated during
117	    /// `exit_variable_declarator` → `init_symbol_value`); function declarations
118	    /// and other binding kinds still take the fallback path.
119	    fn is_symbol_mutated(symbol_id: SymbolId, ctx: &TraverseCtx<'a>) -> bool {
120	        if let Some(sv) = ctx.state.symbol_values.get_symbol_value(symbol_id) {
121	            sv.write_references_count > 0
122	        } else {
123	            ctx.scoping().symbol_is_mutated(symbol_id)
124	        }
125	    }
